import Foundation

struct CardDescriptor {
    let headline: String
    let status: String

    func spokenSummary(combined: Bool) -> String {
        if combined {
            return "\(headline), \(status)"
        }
        return headline
    }
}

let card = CardDescriptor(headline: "Order 101", status: "Shipped")
print(card.spokenSummary(combined: true))

import UIKit

struct TabAccessibility {
    var traits: UIAccessibilityTraits = [.button, .selected]

    var isSelectableButton: Bool {
        traits.contains(.button) && traits.contains(.selected)
    }
}

let tab = TabAccessibility()
print("SelectableButton: \(tab.isSelectableButton)")

import Foundation

struct ElementNode {
    let name: String
    let isHidden: Bool
}

let nodes = [
    ElementNode(name: "TitleLabel", isHidden: false),
    ElementNode(name: "BackgroundArt", isHidden: true),
    ElementNode(name: "ActionButton", isHidden: false)
]

let accessibleNames = nodes.filter { !$0.isHidden }.map { $0.name }
print("Count: \(accessibleNames.count), First: \(accessibleNames[0])")

import Foundation

struct ProgressDescriptor {
    let progress: Double

    var accessibilityValue: String {
        let percentage = Int(progress * 100.0)
        return "\(percentage) percent"
    }
}

let meter = ProgressDescriptor(progress: 0.75)
print("Value: \(meter.accessibilityValue)")

import Foundation

struct CustomActionItem {
    let name: String
    let isDestructive: Bool
}

let actions = [
    CustomActionItem(name: "Pin", isDestructive: false),
    CustomActionItem(name: "Delete", isDestructive: true)
]

let actionNames = actions.map { $0.name }.joined(separator: " & ")
print("Rotor actions: \(actionNames)")

import Foundation

enum AccessibilityUpdateType {
    case screenChanged
    case layoutChanged
    case announcement
}

struct FocusNotifier {
    func message(for type: AccessibilityUpdateType) -> String {
        switch type {
        case .screenChanged:
            return "Reset focus to new view"
        case .layoutChanged:
            return "Adjust focus within current view"
        case .announcement:
            return "Speak message without moving focus"
        }
    }
}

let notifier = FocusNotifier()
print(notifier.message(for: .screenChanged))

import Foundation

struct TouchTargetEvaluator {
    let minimumSize: Double = 44.0

    func passesHIG(width: Double, height: Double) -> Bool {
        width >= minimumSize && height >= minimumSize
    }
}

let evaluator = TouchTargetEvaluator()
let smallTarget = evaluator.passesHIG(width: 32.0, height: 44.0)
let fullTarget = evaluator.passesHIG(width: 44.0, height: 48.0)
print("Small: \(smallTarget), Full: \(fullTarget)")

