struct ElementGroupCombiner {
    var children: [String]

    func combinedSpokenText() -> String {
        children.filter { !$0.isEmpty }.joined(separator: ", ")
    }
}

func testCombiner() {
    let combiner = ElementGroupCombiner(children: ["Flight AA", "", "Gate 4"])
    print("Card: \(combiner.combinedSpokenText())")
}

